<template><div class="cm"><slot v-if="tab==='专家'"/><template v-else><div class="cm-tools"><input v-model="search" placeholder="搜索名称或描述"><button @click="adding=!adding">{{tab==='技能'?'添加技能':'添加 MCP 服务'}}</button></div><form v-if="adding" class="cm-form" @submit.prevent="add"><label>名称<input v-model="name" required maxlength="60"></label><label v-if="tab==='技能'">来源方式<select v-model="kind"><option>Git 仓库</option><option>自定义 SKILL.md</option></select></label><label>{{tab==='连接器'?'MCP 服务地址':kind==='Git 仓库'?'开源仓库地址':'技能说明'}}<input v-if="tab==='连接器'||kind==='Git 仓库'" v-model="source" type="url" required placeholder="https://…"><textarea v-else v-model="source" required placeholder="输入技能职责、输入输出及执行步骤"></textarea></label><label v-if="tab==='技能'&&kind==='Git 仓库'">版本／分支<input v-model="version" required placeholder="例如 v1.0.0"></label><p>仅保存配置，待后端校验来源、许可、依赖与权限；不会下载或运行代码。请勿填写密钥。</p><button>保存配置</button></form><p class="cm-note">{{tab==='技能'?'已启用技能可加入当前对话；外部技能需兼容性校验后才能启用。':'MCP 为技能提供外部工具；新增服务当前仅保存配置，不建立连接。'}}</p><article v-for="item in filtered" :key="item.id"><div><strong>{{item.name}}</strong><small>{{item.description}}</small><small v-if="item.source">{{item.source}} {{item.version}}</small><small v-if="item.transport">{{item.transport}}</small><details v-if="item.tools?.length"><summary>查看 {{item.tools.length}} 个工具（源码配置）</summary><code v-for="tool in item.tools" :key="tool">{{tool}}</code></details><a v-if="item.source?.startsWith('https://github.com/')" :href="item.source" target="_blank" rel="noopener noreferrer">开源项目</a><em>{{item.status||'内置配置'}}{{item.enabled?' · 已启用':''}}</em></div><div class="cm-actions"><template v-if="tab==='技能'"><button :disabled="item.external" @click="item.enabled=!item.enabled;save()">{{item.enabled?'停用':'启用'}}</button><button :disabled="!item.enabled" @click="$emit('choose',item)">加入对话</button></template><span v-else>未连接</span><button v-if="item.external" @click="remove(item)">移除</button></div></article><p v-if="!filtered.length" class="cm-note">暂无匹配项</p></template></div></template>
<script setup>
import {localId} from './localId.js'
import {ref,computed,watch,onMounted} from 'vue'
const props=defineProps({initialTab:{type:String,default:'专家'}});const emit=defineEmits(['choose','tab-change']);const tab=ref(props.initialTab),search=ref(''),adding=ref(false),name=ref(''),source=ref(''),kind=ref('Git 仓库'),version=ref(''),items=ref([])
watch(()=>props.initialTab,value=>tab.value=value);watch(tab,value=>emit('tab-change',value))
const defaults=['客户信息查询','历史销量查询','天气查询','用气数据质量检查','销量趋势与异常分析','天气影响分析','事件检索与影响分析','业务知识检索','短期客户用气预测','冬季保供需求预测','月度销量预测','供需缺口评估','预测结果校验','预测报告生成','结果导出'].map((name,i)=>({id:'skill-'+i,name,type:'技能',description:'天然气业务能力配置',enabled:true,external:false}))
try{const cached=JSON.parse(localStorage.getItem('wb-capabilities')||'null');items.value=Array.isArray(cached)?cached:defaults}catch{items.value=defaults}
onMounted(async()=>{try{const response=await fetch('/connectors.json');if(!response.ok)throw Error();const builtins=await response.json();for(const item of builtins){const existing=items.value.findIndex(i=>i.id===item.id);if(existing<0)items.value.push(item);else items.value[existing]=item}save()}catch{}})
const filtered=computed(()=>items.value.filter(i=>i.type===tab.value&&(i.name+i.description).includes(search.value)))
function save(){try{localStorage.setItem('wb-capabilities',JSON.stringify(items.value))}catch{}}
function add(){items.value.push({id:localId(),name:name.value.trim(),source:source.value.trim(),version:version.value,type:tab.value,description:tab.value==='技能'?kind.value:'MCP 连接配置',external:true,enabled:false,status:'待校验'});save();adding.value=false;name.value='';source.value='';version.value=''}
function remove(item){items.value=items.value.filter(i=>i.id!==item.id);save()}
</script>
<style scoped>
.cm-tabs{display:flex;gap:22px;border-bottom:1px solid var(--wb-ui-border);margin:20px 0}.cm-tabs button{padding:10px 0;color:var(--wb-ui-muted);border-bottom:2px solid transparent}.cm-tabs .on{color:var(--wb-ui-secondary);border-color:var(--wb-ui-secondary)}.cm-tools{display:flex;gap:10px;margin:18px 0}.cm-tools input{flex:1;min-width:0}.cm-tools button,.cm-form>button{background:var(--wb-ui-muted);color:white;border:0;border-radius:6px;padding:8px 12px;font-size:var(--wb-font-control)}input,textarea,select{font:inherit;font-size:var(--wb-font-control);border:1px solid var(--wb-ui-border);border-radius:6px;padding:9px;color:var(--wb-ui-secondary);background:white}article{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid var(--wb-ui-border);border-radius:9px;padding:14px;margin:9px 0}article>div:first-child{min-width:0}strong{font-size:var(--wb-font-body);color:var(--wb-ui-secondary)}small{display:block;font-size:var(--wb-font-meta);color:var(--wb-ui-muted);overflow-wrap:anywhere;margin-top:5px}em{display:block;font-size:var(--wb-font-meta);color:var(--wb-ui-muted);font-style:normal;margin-top:7px}.cm-actions{display:flex;gap:8px;flex-shrink:0;font-size:var(--wb-font-meta);color:var(--wb-ui-muted)}.cm-actions button{color:var(--wb-ui-muted);font-size:var(--wb-font-meta)}.cm-actions button:disabled{color:var(--wb-ui-muted);cursor:default}.cm-form{background:var(--wb-ui-surface);padding:16px;border-radius:9px}.cm-form label{display:block;font-size:var(--wb-font-control);color:var(--wb-ui-secondary);margin-bottom:12px}.cm-form input,.cm-form textarea,.cm-form select{display:block;width:100%;margin-top:7px}.cm-form textarea{min-height:100px}.cm-note,.cm-form p{font-size:var(--wb-font-meta);color:var(--wb-ui-muted);line-height:1.8;margin:12px 0}
details{font-size:var(--wb-font-meta);color:var(--wb-ui-secondary);margin-top:10px}code{display:block;font-size:var(--wb-font-meta);margin:5px 0;padding-left:10px}article a{display:inline-block;color:var(--wb-ui-muted);font-size:var(--wb-font-meta);margin-top:8px}
</style>
